WITH flattened AS (SELECT id, log_ts, level, status_code, key, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS key, v), parsed AS (SELECT id, level, status_code, key, v, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 1) != 0 AS INT) AS is_flagged FROM flattened WHERE level = 'ERROR'), with_windows AS (SELECT id, level, status_code, key, v, status_code_high, is_flagged, AVG(status_code) OVER (PARTITION BY level, key) AS level_avg_status_code, MAX(status_code) OVER (PARTITION BY key, level) AS key_max_status_code, SUM(is_flagged) OVER (PARTITION BY level ORDER BY status_code_high, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_is_flagged FROM parsed), enriched AS (SELECT id, level, status_code, key, v, status_code_high, is_flagged, level_avg_status_code, key_max_status_code, running_is_flagged, ROUND(level_avg_status_code / SUM(level_avg_status_code) OVER (PARTITION BY level, key), 4) AS level_avg_status_code_share, SUM(key_max_status_code) OVER (PARTITION BY level, key ORDER BY status_code, id, key ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_key_max_status_code FROM with_windows), matched_keys AS (SELECT level, id FROM enriched EXCEPT ALL SELECT level, id FROM app_logs WHERE service IN ('billing', 'auth', 'search')), verified AS (SELECT s.* FROM enriched s INNER JOIN matched_keys k ON s.level = k.level AND s.id = k.id), remaining_keys AS (SELECT level, id FROM verified EXCEPT ALL SELECT level, id FROM app_logs WHERE host = 'h4'), verified_app_logs AS (SELECT s.* FROM verified s INNER JOIN remaining_keys k ON s.level = k.level AND s.id = k.id), pivoted AS (SELECT * FROM (SELECT level, key, is_flagged FROM verified_app_logs) src PIVOT (AVG(is_flagged) AS total, COUNT(1) AS cnt FOR key IN ('version', 'region', 'trace'))) SELECT level, version_total, version_cnt, trace_cnt FROM pivoted ORDER BY level;
